function isBipartite(graph) {
  const n = graph.length;
  const color = new Array(n).fill(-1);      // -1: not coloured yet
  for (let s = 0; s < n; s++) {
    if (color[s] !== -1) continue;          // already coloured by an earlier search
    color[s] = 0;
    const queue = [s];
    let head = 0;
    while (head < queue.length) {
      const u = queue[head++];
      for (const v of graph[u]) {
        if (color[v] === -1) {
          color[v] = 1 - color[u];          // a neighbour must take the other colour
          queue.push(v);
        } else if (color[v] === color[u]) {
          return false;                     // both ends of an edge share a colour
        }
      }
    }
  }
  return true;
}

from collections import deque

def is_bipartite(graph):
    n = len(graph)
    color = [-1] * n                      # -1: not coloured yet
    for s in range(n):
        if color[s] != -1:
            continue                      # already coloured by an earlier search
        color[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]   # a neighbour must take the other colour
                    queue.append(v)
                elif color[v] == color[u]:
                    return False          # both ends of an edge share a colour
    return True

boolean isBipartite(int[][] graph) {
    int n = graph.length;
    int[] color = new int[n];
    Arrays.fill(color, -1);                      // -1: not coloured yet
    for (int s = 0; s < n; s++) {
        if (color[s] != -1) continue;            // already coloured by an earlier search
        color[s] = 0;
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        queue.add(s);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : graph[u]) {
                if (color[v] == -1) {
                    color[v] = 1 - color[u];     // a neighbour must take the other colour
                    queue.add(v);
                } else if (color[v] == color[u]) {
                    return false;                // both ends of an edge share a colour
                }
            }
        }
    }
    return true;
}

